import{_ as t,c as e,o as a,ae as o}from"./chunks/framework.ChBuoQPj.js";const h=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"introduce.md","filePath":"introduce.md"}'),n={name:"introduce.md"};function i(l,r,s,d,u,c){return a(),e("div",null,r[0]||(r[0]=[o('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><p><code>Markdown Editor</code> 是基于Vue3开发打造的高效、灵活且功能丰富的 Markdown 编辑工具。 为开发者与用户提供了便捷的使用体验。</p><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><strong>响应式设计</strong>：充分利用 Vue 3 的响应式系统，当输入内容发生变化时，编辑器能够实时更新预览，让用户即时看到 Markdown 转换后的效果。</li><li><strong>组合式 API</strong>：采用 Vue 3 的组合式 API，使得代码逻辑更加清晰、可复用，便于开发者进行功能扩展和定制。</li><li><strong>标准语法支持</strong>：支持完整的 Markdown 标准语法，包括标题、列表、代码块、引用、链接等，满足日常文档编写的基本需求。</li><li><strong>实时预览</strong>：编辑器提供实时预览功能，用户在输入 Markdown 内容的同时，右侧预览区域会实时更新渲染结果，方便用户及时查看和调整内容。</li><li><strong>快捷键支持</strong>：支持丰富的快捷键操作，如加粗、倾斜、插入链接、插入代码块等，提高用户的输入效率。</li><li><strong>代码高亮</strong>：对于代码块，编辑器提供多种语言的代码高亮显示，增强代码的可读性。</li><li><strong>同步滚动</strong>：编辑预览实时同步滚动，精准高效。</li></ul><h2 id="贡献与支持" tabindex="-1">贡献与支持 <a class="header-anchor" href="#贡献与支持" aria-label="Permalink to &quot;贡献与支持&quot;">​</a></h2><p>欢迎社区开发者的贡献！如果你发现了 bug 或者有新的功能建议，欢迎在我们的 GitHub 仓库提交 issue 或 pull request。同时，如果你在使用过程中遇到任何问题，也可以在社区中寻求帮助。</p><p><a href="https://github.com/wangruichuan/vue-markdown-editor" target="_blank" rel="noreferrer">GitHub 仓库链接</a></p>',7)]))}const g=t(n,[["render",i]]);export{h as __pageData,g as default};
